-- CTET Syllabus Tracker — full reseed, generated from CTET-February 2026 Information Bulletin (Appendix I)
-- Run this once in Supabase Dashboard -> SQL Editor -> New query, on your CTET project.
--
-- Exam-tag scheme (matches lib/features/syllabus/presentation/syllabus_navigation.dart's
-- resolveSyllabusTopicTags, which decomposes an admin-named leaf folder like
-- "Science(Hin Eng)" into the tags below rather than needing every one of the
-- ~36 language-pair leaves to duplicate this content under its own exact name):
--   'CTET'                    -> Child Development and Pedagogy (shared by every leaf)
--   'CTET Paper 1'            -> Mathematics + Environmental Studies (P-1(...) leaves)
--   'CTET Paper 2 Science'    -> Mathematics and Science (Science(...) leaves)
--   'CTET Paper 2 SST'        -> Social Studies/Social Sciences (SST(...) leaves)
--   'Language I (<Lang>)' / 'Language II (<Lang>)' -> per the leaf's chosen language pair
-- syllabus_marks_distribution stays keyed by the leaf's parent folder name
-- ('CTET Paper 1' / 'CTET Paper 2'), since that's a real folder in the catalog.

begin;

-- 1) Wipe existing syllabus content
delete from public.syllabus_progress;  -- FK references syllabus_topics.id, must go first
delete from public.syllabus_topics;
delete from public.syllabus_marks_distribution;

-- 2) Syllabus topics

-- 3) Marks distribution (Appendix I, Structure and Content)
  ["Subject", "MCQs", "Marks"],
  ["Child Development and Pedagogy", "30", "30"],
  ["Mathematics", "30", "30"],
  ["Environmental Studies", "30", "30"],
  ["Language I", "30", "30"],
  ["Language II", "30", "30"],
  ["Total", "150", "150"]
]'::jsonb),
('CTET Paper 2', '[
  ["Subject", "MCQs", "Marks"],
  ["Child Development and Pedagogy", "30", "30"],
  ["Mathematics and Science (for Maths/Science teacher) OR Social Studies/Social Science (for SSt teacher)", "60", "60"],
  ["Language I", "30", "30"],
  ["Language II", "30", "30"],
  ["Total", "150", "150"]
]'::jsonb)
on conflict (exam) do update set table_data = excluded.table_data;

commit;
